            "format": "int32",
            "type": "integer"
          },
          "pageToken": {
            "description": "Optional. A page token, received from a previous list_messages call. Provide this to retrieve the subsequent page.",
            "type": "string"
          },
          "startTime": {
            "description": "Optional. ISO 8601 timestamp to filter messages. Only messages created after this time will be returned.",
            "type": "string"
          },
          "threadId": {
            "description": "Optional. The ID of a specific thread within the conversation. If provided, only messages from this thread will be returned. If omitted, messages from all threads in the conversation are considered. Format: spaces/{space}/threads/{thread}",
            "type": "string"
          }
        },
        "required": [
          "conversationId"
        ]
      }
    },
    {
      "tool": "search_conversations",
      "description": "Searches for Google Chat conversations (named spaces, direct messages (DMs), or group chats) by display name or participants to find conversation IDs. This tool searches conversation metadata, NOT message contents. To search within message history or find messages by keyword/sender/timestamp, use search_messages. If only participants are provided, this tool finds 1:1 direct messages (if one participant is provided) or group chats (if multiple participants are provided) that include the specified participants and the calling user. If only a query is provided, this tool searches for conversations where the query is a case-insensitive substring of the conversation's display name. If both participants and query are provided, this tool finds conversations by participants and then filters them by display name. If neither participants nor query are provided, this tool lists all conversations the calling user is a member of. This tool only lists conversations the calling user is a member of. Returns a list of conversation objects containing conversation IDs (format: spaces/{space}), display names, and conversation types. IMPORTANT: An empty 'conversations' list does not mean there are no more results overall. If 'next_page_token' is present, more pages can be fetched. If you get an empty list but a 'next_page_token', ask the user if you should continue the searching.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pageSize": {
            "description": "Optional. The maximum number of spaces to return. The service may return fewer than this value. If unspecified, at most 20 spaces will be returned. The maximum value is 1000; values above 1000 will be coerced to 1000.",
            "format": "int32",
            "type": "integer"
          },
          "pageToken": {
            "description": "Optional. A page token, received from a previous `search_conversations` call. Provide this to retrieve the subsequent page.",
            "type": "string"
          },
          "participants": {
            "description": "Optional. List of email addresses of the participants to filter the conversations, excluding the caller.",
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "spaceNameQuery": {
            "description": "Optional. The text to search for within the space display names (case-insensitive substring match).",
            "type": "string"
          }
        }
      }
    },
    {
      "tool": "search_messages",
      "description": "Searches for Google Chat messages using keywords and filters returning them in Markdown format. Works across all spaces the user has access to, or can be scoped to a specific conversation. Follow this guidance when deciding to use search_messages vs other search or read tools: - Use search_messages when looking for specific message content, keywords, mentions, links, senders or unread messages potentially across multiple spaces or without a known conversation ID. - Use list_messages when you know the specific space or thread ID and want to read messages sequentially in chronological order. - Use search_conversations to find space metadata such as conversation IDs by space display name or participants (it searches metadata only, not message contents). If searchParameters is provided without specific filters, recent messages across conversations accessible to the user are returned.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pageSize": {
            "description": "Optional. The maximum number of results to return (max up to 100). If unspecified, at most 25 are returned.",
            "format": "int32",
            "type": "integer"
          },
          "pageToken": {
            "description": "Optional. A page token, received from a previous `search_messages` call. Provide this to retrieve the subsequent page.",
            "type": "string"
          },
          "searchParameters": {
            "$ref": "#/$defs/SearchParameters",
            "description": "Required. The search parameters to use for the search."
          }
        },
        "required": [
          "searchParameters"
        ],
        "$defs": {
          "SearchParameters": {
            "description": "Configures the parameters used for searching messages. If `search_parameters` is provided with no sub-fields set, recent messages across conversations accessible to the user are returned.",
            "properties": {
              "conversationId": {
                "description": "Optional. Scopes the search to a specific conversation identifier, as returned from the search_conversations tool. Format: `spaces/{ID}`.",
                "type": "string"
              },
              "conversationIncludesUser": {
                "description": "Optional. Filter for messages in DMs and group chats that include the specific user email or ID.",
                "type": "string"
              },
              "endTime": {
                "description": "Optional. Filter for messages created before this time. Format: ISO 8601 timestamp.",
                "type": "string"
              },
              "hasLink": {
                "description": "Optional. Filter for messages containing at least one URL.",
                "type": "boolean"
              },
              "isUnread": {
                "description": "Optional. Filter for messages that have not been read by the calling user.",
                "type": "boolean"
              },
              "keywords": {
                "description": "Optional. A set of keywords which are used to filter the results.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "mentionsMe": {
                "description": "Optional. Filter for messages that explicitly mention the calling user.",
                "type": "boolean"
              },
              "sender": {
                "description": "Optional. Filter for messages from a specific user. Either the email or resource name of the sender can be used. User resource names are formatted as `users/{ID}`, where `{ID}` can be a person ID or their email address.",
                "type": "string"
              },
              "spaceDisplayNames": {
                "description": "Optional. Filter by a list of space names; space display names are partially matched. Note: Only the top 5 matches are returned.",
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              "startTime": {
                "description": "Optional. Filter for messages created after this time. Format: ISO 8601 timestamp.",
                "type": "string"
              }
            },
            "type": "object"
          }
        }
      }
    },
    {
      "tool": "send_message",
      "description": "Sends a Google Chat message to a conversation with Markdown formatting. This tool uses a conversation ID, an optional thread ID, and a message text as inputs. Conversation ID's can be found using the search_conversations tool. It returns the created message.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "conversationId": {
            "description": "Required. The ID of the conversation (e.g., 'spaces/AAAA...') to send the message to.",
            "type": "string"
          },
          "messageText": {
            "description": "Required. The main content of the message. Formatting can be added using standard Markdown (note that tables are NOT supported). The following formatting is supported: * **Bold:** `**text**` * **Italic:** `*text*` or `_text_` * **Strikethrough:** `~~text~~` * **Monospace:** `text` * **Monospace block:** ``` line 1 line 2 ``` * **Bulleted list:** * item 1 * item 2 * **Ordered list:** 1. item 1 2. item 2 * **Block quote:** `> quoted text` * **Hyperlink:** `[label](url)` * **Mention user:** Use a self-closing HTML tag `chat-user` with attributes `data-email=\"user@example.com\"` or `data-user=\"users/USER_ID\"`. Prefer the `data-user` attribute with `USER_ID` if known and fall back to the data-email attribute with the user email otherwise. If you use the `data-user` attribute make sure to include the users/ prefix seen in other tool return values. Note: A maximum of 10 mentions are allowed per message. Mentioning all users (e.g., using `@all` or an HTML tag with `users/all`) is strictly prohibited. * **Custom emoji:** Use a self-closing HTML tag `chat-emoji` with attributes `data-custom-emoji=\"customEmojis/abc\"` or `data-emoji-name=\":xyz:\"`.",
            "type": "string"
          },
          "threadId": {
            "description": "Optional. The ID of the thread (e.g., 'spaces/AAAA.../threads/BBBB...') to send the message to. If not set, the message will be sent to a new thread.",
            "type": "string"
          }
        },
        "required": [
          "conversationId",
          "messageText"
        ]
      }
    }
  ]
}

